-- Latched binding revocations survive rapid revoke/regrant and out-of-order delivery.
CREATE TABLE group_expert_binding_revocations (
    conversation_id TEXT NOT NULL,
    source_agent_id TEXT NOT NULL,
    source_row_id BIGINT NOT NULL,
    before_revision BIGINT NOT NULL,
    PRIMARY KEY(conversation_id,source_agent_id,source_row_id)
);
CREATE TRIGGER group_expert_binding_agent_update BEFORE UPDATE ON agents WHEN OLD.enabled IS NOT NEW.enabled OR OLD.user_id IS NOT NEW.user_id OR OLD.kind IS NOT NEW.kind BEGIN
INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE json_extract(v.value,'$.source_agent_id')=OLD.agent_id AND json_extract(v.value,'$.source_row_id')=OLD.id) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) SELECT 'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,'invalidate','bindings:'||conversation_id,json_object('domain_key','bindings:'||conversation_id,'revision',cutoff,'revocations',json_array(json_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff))),'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,CAST(strftime('%s','now') AS INTEGER) FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE json_extract(v.value,'$.source_agent_id')=OLD.agent_id AND json_extract(v.value,'$.source_row_id')=OLD.id) WHERE true ON CONFLICT(operation_id) DO NOTHING;
END;
CREATE TRIGGER group_expert_binding_agent_delete BEFORE DELETE ON agents WHEN 1 BEGIN
INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE json_extract(v.value,'$.source_agent_id')=OLD.agent_id AND json_extract(v.value,'$.source_row_id')=OLD.id) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) SELECT 'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,'invalidate','bindings:'||conversation_id,json_object('domain_key','bindings:'||conversation_id,'revision',cutoff,'revocations',json_array(json_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff))),'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,CAST(strftime('%s','now') AS INTEGER) FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE json_extract(v.value,'$.source_agent_id')=OLD.agent_id AND json_extract(v.value,'$.source_row_id')=OLD.id) WHERE true ON CONFLICT(operation_id) DO NOTHING;
END;
CREATE TRIGGER group_expert_binding_owner BEFORE UPDATE ON expert_assignment_source WHEN OLD.source_user_id IS NOT NEW.source_user_id BEGIN
INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE EXISTS(SELECT 1 FROM agents a WHERE a.user_id=OLD.source_user_id AND a.agent_id=json_extract(v.value,'$.source_agent_id') AND a.id=json_extract(v.value,'$.source_row_id'))) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) SELECT 'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,'invalidate','bindings:'||conversation_id,json_object('domain_key','bindings:'||conversation_id,'revision',cutoff,'revocations',json_array(json_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff))),'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,CAST(strftime('%s','now') AS INTEGER) FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE EXISTS(SELECT 1 FROM agents a WHERE a.user_id=OLD.source_user_id AND a.agent_id=json_extract(v.value,'$.source_agent_id') AND a.id=json_extract(v.value,'$.source_row_id'))) WHERE true ON CONFLICT(operation_id) DO NOTHING;
END;
CREATE TRIGGER group_expert_binding_user BEFORE UPDATE ON users WHEN OLD.disabled IS NOT NEW.disabled OR OLD.role IS NOT NEW.role BEGIN
INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE EXISTS(SELECT 1 FROM agents a,expert_assignment_source p WHERE p.source_user_id=OLD.id AND a.user_id=OLD.id AND a.agent_id=json_extract(v.value,'$.source_agent_id') AND a.id=json_extract(v.value,'$.source_row_id'))) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) SELECT 'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,'invalidate','bindings:'||conversation_id,json_object('domain_key','bindings:'||conversation_id,'revision',cutoff,'revocations',json_array(json_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff))),'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,CAST(strftime('%s','now') AS INTEGER) FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE EXISTS(SELECT 1 FROM agents a,expert_assignment_source p WHERE p.source_user_id=OLD.id AND a.user_id=OLD.id AND a.agent_id=json_extract(v.value,'$.source_agent_id') AND a.id=json_extract(v.value,'$.source_row_id'))) WHERE true ON CONFLICT(operation_id) DO NOTHING;
END;
CREATE TRIGGER group_expert_binding_department_update BEFORE UPDATE ON department_resource_pools WHEN OLD.expert_ids IS NOT NEW.expert_ids BEGIN
INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE s.department_id=OLD.scope_id AND json_extract(v.value,'$.source_agent_id') IN(SELECT value FROM json_each(OLD.expert_ids) EXCEPT SELECT value FROM json_each(NEW.expert_ids))) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) SELECT 'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,'invalidate','bindings:'||conversation_id,json_object('domain_key','bindings:'||conversation_id,'revision',cutoff,'revocations',json_array(json_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff))),'bindings:'||conversation_id||':'||source_id||':'||row_id||':'||cutoff,CAST(strftime('%s','now') AS INTEGER) FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE s.department_id=OLD.scope_id AND json_extract(v.value,'$.source_agent_id') IN(SELECT value FROM json_each(OLD.expert_ids) EXCEPT SELECT value FROM json_each(NEW.expert_ids))) WHERE true ON CONFLICT(operation_id) DO NOTHING;
END;
