INSERT INTO group_expert_binding_revocations SELECT conversation_id,source_id,row_id,cutoff FROM (SELECT s.conversation_id,json_extract(v.value,'$.source_agent_id') source_id,CAST(json_extract(v.value,'$.source_row_id') AS INTEGER) row_id,s.revision+1 cutoff FROM group_expert_scopes s,json_each(s.sources_json) v WHERE s.department_id=OLD.scope_id AND json_extract(v.value,'$.source_agent_id') IN(SELECT value FROM json_each(OLD.expert_ids))) WHERE true ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=MAX(before_revision,excluded.before_revision);
